      "uuid": "11111111-2222-3333-4444-555555555555",
      "flow": "xtls-rprx-vision",
      "tls": {
        "enabled": true,
        "server_name": "tls.example.com",
        "certificate_sha256": "42957407083C64B94A232105C46980A8002E5054F5CF1282851A8F52B448F511"
      }
    },
    {
      "tag": "tls-vision-2",
      "server": "9.10.11.12",
      "server_port": 24443,
      "type": "vless",
      "uuid": "11111111-2222-3333-4444-555555555555",
      "flow": "xtls-rprx-vision",
      "tls": {
        "enabled": true,
        "server_name": "tls.example.com",
        "certificate_sha256": "42957407083C64B94A232105C46980A8002E5054F5CF1282851A8F52B448F511"
      }
    },
    {
      "tag": "vmess-ws",
      "server": "cdn.example.com",
      "server_port": 2053,
      "type": "vmess",
      "uuid": "11111111-2222-3333-4444-555555555555",
      "security": "auto",
      "alter_id": 0,
      "transport": {
        "type": "ws",
        "path": "/ws",
        "headers": {
          "Host": "cdn.example.com"
        }
      },
      "tls": {
        "enabled": true,
        "server_name": "cdn.example.com",
        "certificate_sha256": "42957407083C64B94A232105C46980A8002E5054F5CF1282851A8F52B448F511"
      }
    },
    {
      "tag": "trojan-grpc",
      "server": "1.2.3.4",
      "server_port": 2087,
      "type": "trojan",
      "password": "pw-alice",
      "transport": {
        "type": "grpc",
        "service_name": "GunService"
      },
      "tls": {
        "enabled": true,
        "server_name": "grpc.example.com",
        "certificate_sha256": "42957407083C64B94A232105C46980A8002E5054F5CF1282851A8F52B448F511"
      }
    },
    {
      "tag": "ss2022",
      "server": "1.2.3.4",
      "server_port": 8388,
      "type": "shadowsocks",
      "method": "2022-blake3-aes-128-gcm",
      "password": "AAECAwQFBgcICQoLDA0ODw==:2RDhizjitM2kceOTR8MSCA=="
    },
    {
      "tag": "hy2",
      "server": "1.2.3.4",
      "server_port": 8443,
      "type": "hysteria2",
      "password": "EJeIPa4oJCPnIy/RFJrb7lxvAV/1dxKicp4dRV5MFxQ=",
      "up_mbps": 60,
      "down_mbps": 150,
      "tls": {
        "enabled": true,
        "server_name": "front.example.com",
        "alpn": [
          "h3"
        ],
        "certificate_public_key_sha256": [
          "tjfPZFMqGHy9VdTnlSyZmljdgFqalB8eEnF5OoPu5Dw="
        ]
      }
    },
    {
      "tag": "vless-hu",
      "server": "1.2.3.4",
      "server_port": 2095,
      "type": "vless",
      "uuid": "11111111-2222-3333-4444-555555555555",
      "transport": {
        "type": "httpupgrade",
        "path": "/hu",
        "host": "hu.example.com"
      }
    },
    {
      "tag": "bad-reality",
      "server": "1.2.3.4",
      "server_port": 444,
      "type": "vless",
      "uuid": "11111111-2222-3333-4444-555555555555",
      "tls": {
        "enabled": true,
        "server_name": "x.com",
        "utls": {
          "enabled": true,
          "fingerprint": "chrome"
        },
        "reality": {
          "enabled": true,
          "public_key": "",
          "short_id": ""
        }
      }
    },
    {
      "type": "selector",
      "tag": "PROXY",
      "outbounds": [
        "reality-tcp",
        "tls-vision-1",
        "tls-vision-2",
        "vmess-ws",
        "trojan-grpc",
        "ss2022",
        "hy2",
        "vless-hu",
        "bad-reality",
        "direct"
      ],
      "default": "reality-tcp"
    },
    {
      "type": "direct",
      "tag": "direct"
    }
  ],
  "dns": {
    "servers": [
      {
        "tag": "doh-cn",
        "type": "https",
        "server": "223.5.5.5",
        "path": "/dns-query"
      },
      {
        "tag": "doh-proxy",
        "type": "https",
        "server": "1.1.1.1",
        "path": "/dns-query",
        "detour": "PROXY"
      }
    ],
    "rules": [
      {
        "rule_set": "geosite-cn",
        "server": "doh-cn"
      }
    ],
    "final": "doh-proxy",
    "strategy": "prefer_ipv4"
  },
  "route": {
    "default_domain_resolver": "doh-proxy",
    "rule_set": [
      {
        "tag": "geosite-cn",
        "type": "remote",
        "format": "binary",
        "url": "https://raw.githubusercontent.com/SagerNet/sing-geosite/rule-set/geosite-cn.srs",
        "download_detour": "PROXY"
      },
      {
        "tag": "geosite-ads",
        "type": "remote",
        "format": "binary",
        "url": "https://raw.githubusercontent.com/SagerNet/sing-geosite/rule-set/geosite-category-ads-all.srs",
        "download_detour": "PROXY"
      },
      {
        "tag": "geoip-cn",
        "type": "remote",
        "format": "binary",
        "url": "https://raw.githubusercontent.com/SagerNet/sing-geoip/rule-set/geoip-cn.srs",
        "download_detour": "PROXY"
      }
    ],
    "rules": [
      {
        "action": "sniff"
      },
      {
        "protocol": "dns",
        "action": "hijack-dns"
      },
      {
        "ip_is_private": true,
        "action": "route",
        "outbound": "direct"
      },
      {
        "rule_set": "geosite-ads",
        "action": "reject"
      },
      {
        "rule_set": "geosite-cn",
        "action": "route",
        "outbound": "direct"
      },
      {
        "rule_set": "geoip-cn",
        "action": "route",
        "outbound": "direct"
      }
    ],
    "final": "PROXY"
  }
}

